actions.script:
def CourseAiUtil = ec.resource.script("component://growerp/service/course/CourseAiUtil.groovy", null)
if (CourseAiUtil.testMode()) {
    answer = mode == 'HINTS' ? "Hint: look again at the key points of this lesson." :
        "Test tutor answer to: ${message}"
} else {
    def GeminiAiUtil = ec.resource.script("component://growerp/service/GeminiAiUtil.groovy", null)
    StringBuilder prompt = new StringBuilder()
    prompt << "You are a patient, encouraging tutor for the online course \"${course.title}\".\n"
    if (course.objectives) prompt << "Course objectives: ${course.objectives}\n"
    if (course.audience) prompt << "Audience: ${course.audience}\n"
    if (course.difficulty) prompt << "Level: ${course.difficulty}\n"
    if (lesson) {
        prompt << "\nThe learner is studying module \"${module?.title ?: ''}\", lesson \"${lesson.title}\".\n"
        prompt << "LESSON CONTENT:\n${(lesson.content ?: '').take(12000)}\n"
        if (lesson.keyPoints) prompt << "KEY POINTS: ${lesson.keyPoints}\n"
    }
    if (extraContext) prompt << "\nCONTEXT:\n${extraContext.take(6000)}\n"
    prompt << "\nRULES:\n"
    prompt << "- Base your answer on the lesson content; use general knowledge only to clarify it.\n"
    prompt << "- If the question is not about the course topic, say so briefly and steer back to the course.\n"
    prompt << "- Answer in the language of the learner's last message. Be concise: at most about 200 words. Use Markdown.\n"
    if (mode == 'HINTS') {
        prompt << "- HINTS MODE: never give the full answer or solution, even if asked. " +
            "Ask one guiding question or give one small hint at a time, " +
            "and tell the learner whether they are on the right track.\n"
    } else {
        prompt << "- Explain clearly, with a short example where it helps.\n"
    }
    def turns = (history ?: []).takeRight(10)
    if (turns) {
        prompt << "\nCONVERSATION SO FAR:\n"
        turns.each { Map t -> prompt << "${t.role == 'tutor' ? 'Tutor' : 'Learner'}: ${t.text}\n" }
    }
    prompt << "\nLearner: ${message}\nTutor:"
    answer = GeminiAiUtil.callLlmApi(ec, prompt.toString(),
        [ownerPartyId: access.ownerPartyId, maxOutputTokens: 2048])?.trim()
}
